struct State {std::array<std::byte,256> calibration{};std::vector<Pose> poses;std::vector<V> points;};
struct Data {std::vector<unsigned> active;std::vector<Observation> observations;std::vector<std::vector<unsigned>> by_point;std::vector<unsigned> starts;std::vector<IntrinsicPrior> priors;unsigned n{};std::vector<unsigned> parameters{fitted.begin(),fitted.end()};bool captured_stage{};unsigned iteration_limit{50};double tolerance{1e-10};};
constexpr M identity{1,0,0,0,1,0,0,0,1};
void initial_calibration(State& s,std::uint64_t width,std::uint64_t height){s.calibration=photo_initial::no_exif_calibration(width,height);}
void prepare(fs::path input,fs::path out,bool stage=false){if(fs::exists(out))throw std::runtime_error("output exists");auto sensor=read_bytes(input/"scene_vector_13.bin"),position=read_bytes(input/"scene_vector_16.bin"),rotation=read_bytes(input/"scene_vector_19.bin"),cameras=read_bytes(input/"scene_vector_22.bin");auto header=read_bytes(input/"problem_header.bin");if(sensor.size()!=616||position.size()%120||rotation.size()%312||cameras.size()%424||get<M>(sensor.data(),512)!=identity||get<V>(sensor.data(),584)!=V{}||sensor[288]!=std::byte{1}||sensor[289]!=std::byte{1}||(get<unsigned>(sensor.data(),272)!=3527&&!(stage&&get<unsigned>(sensor.data(),272)==193))||get<int>(header.data(),28)!=0||get<double>(header.data(),40)!=1)throw std::runtime_error("unsupported capture scene");for(unsigned i=34;i<=61;i+=3)if(!(stage&&i==37)&&!read_bytes(input/("scene_vector_"+std::to_string(i)+".bin")).empty())throw std::runtime_error("additional constraints not supported");if(!read_bytes(input/"external_288.bin").empty()||!read_bytes(input/"scene_vector_31.bin").empty())throw std::runtime_error("auxiliary/infinite point branch");
 std::vector<Pose> poses;for(std::size_t i=0;i<cameras.size()/424;++i){auto c=cameras.data()+424*i;if(get<int>(c,8)!=int(i)||get<int>(c,12)!=0||get<M>(c,296)!=identity||get<V>(c,368)!=V{}||get<unsigned>(c,288))throw std::runtime_error("camera mapping/extra calibration");if((i+1)*120>position.size()||(i+1)*312>rotation.size())throw std::runtime_error("pose extent");Pose p;std::memcpy(p.position.data(),position.data()+120*i,120);p.rotation=get<M>(rotation.data()+312*i,240);p.rotation_fixed=rotation[312*i+20]!=std::byte{};poses.push_back(p);}
 auto rawpoints=read_bytes(input/"external_312.bin");if(rawpoints.size()%48)throw std::runtime_error("point records");std::vector<V> points;for(std::size_t i=0;i<rawpoints.size();i+=48)points.push_back(get<V>(rawpoints.data()+i,0));auto active=read_array<unsigned>(input/"scene_vector_28.bin");auto obs=read_array<Observation>(input/"external_240.bin");
 if(stage){auto map=read_array<unsigned>(input/"camera_map.bin");std::vector<Observation> mapped;for(auto o:obs){if(o.camera>=map.size())throw std::runtime_error("camera map extent");auto id=map[o.camera];if(id==UINT_MAX)continue;if(id>=poses.size())throw std::runtime_error("camera map target");o.camera=id;mapped.push_back(o);}obs=std::move(mapped);}

 fs::create_directories(out);std::vector<double> posevalues;std::vector<unsigned> flags;for(auto& p:poses){flags.push_back(position_dof(p));flags.push_back(p.rotation_fixed);auto c=center(p);posevalues.insert(posevalues.end(),c.begin(),c.end());posevalues.insert(posevalues.end(),p.rotation.begin(),p.rotation.end());auto origin=position_dof(p)==2?get<V>(p.position.data(),16):V{};posevalues.insert(posevalues.end(),origin.begin(),origin.end());posevalues.push_back(position_dof(p)==2?get<double>(p.position.data(),40):0);for(unsigned k=0;k<2;++k){auto v=position_dof(p)==2?position_basis(p,k):V{};posevalues.insert(posevalues.end(),v.begin(),v.end());}}
 write_array(out/"poses.bin",posevalues);write_array(out/"pose_flags.bin",flags);write_array(out/"points.bin",points);write_array(out/"active_points.bin",active);write_array(out/"observations.bin",obs);write_array(out/"image_size.bin",std::vector<std::uint64_t>{get<std::uint64_t>(sensor.data(),24),get<std::uint64_t>(sensor.data(),32)});
 if(stage){auto priors=read_array<IntrinsicPrior>(input/"scene_vector_37.bin");for(auto& p:priors)if(get<unsigned>(p.data(),0)!=0)throw std::runtime_error("multiple prior sensors");write_array(out/"calibration_priors.bin",priors);auto settings=read_bytes(input.parent_path()/"object_before.bin");if(settings.size()!=704)throw std::runtime_error("optimizer settings extent");write_array(out/"captured_optimizer_settings.bin",std::vector<double>{double(get<unsigned>(settings.data(),664)),get<double>(settings.data(),672)});write_bytes(out/"captured_initial_calibration.bin",std::span<const std::byte>(sensor.data()+16,256));write_array(out/"captured_fitted_mask.bin",std::vector<unsigned>{get<unsigned>(sensor.data(),272)});}
 std::ofstream(out/"provenance.json")<<"{\"source\":\"initial native scene before optimizer iterations\",\"captured_initial_intrinsics_included\":"<<(stage?"true":"false")<<",\"captured_final_intrinsics_included\":false,\"normal_equations_included\":false,\"native_initial_poses_and_sparse_points_used\":true,\"photos_only\":false}";
}
std::pair<State,Data> load(fs::path input,bool stage=false){State s;Data d;auto size=read_array<std::uint64_t>(input/"image_size.bin");if(size.size()!=2||!size[0]||!size[1])throw std::runtime_error("image size");initial_calibration(s,size[0],size[1]);
 if(stage){d.priors=read_array<IntrinsicPrior>(input/"calibration_priors.bin");auto c=read_bytes(input/"captured_initial_calibration.bin");auto mask=read_array<unsigned>(input/"captured_fitted_mask.bin");if(c.size()!=256||mask.size()!=1||(mask[0]!=193&&mask[0]!=3527))throw std::runtime_error("captured stage calibration format");std::copy(c.begin(),c.end(),s.calibration.begin());d.parameters.clear();for(auto bit:fitted)if(mask[0]&(1u<<bit))d.parameters.push_back(bit);auto settings=read_array<double>(input/"captured_optimizer_settings.bin");if(settings.size()!=2||settings[0]<0||settings[0]>1000||settings[1]<0||!std::isfinite(settings[1]))throw std::runtime_error("stage optimizer settings");d.iteration_limit=unsigned(settings[0]);d.tolerance=settings[1];d.captured_stage=true;}
auto values=read_array<double>(input/"poses.bin");auto flags=read_array<unsigned>(input/"pose_flags.bin");if(values.empty()||values.size()%22||flags.size()!=values.size()/11)throw std::runtime_error("pose format");for(unsigned i=0;i<flags.size()/2;++i){Pose p;auto a=values.data()+22*i;unsigned n=flags[2*i];if(n!=0&&n!=2&&n!=3)throw std::runtime_error("pose DOF");p.position[8]=std::byte(n==0);p.position[9]=std::byte(n==2);set(p.position.data(),96,V{a[0],a[1],a[2]});std::copy(a+3,a+12,p.rotation.begin());set(p.position.data(),16,V{a[12],a[13],a[14]});set(p.position.data(),40,a[15]);set(p.position.data(),48,V{a[16],a[17],a[18]});set(p.position.data(),72,V{a[19],a[20],a[21]});p.rotation_fixed=flags[2*i+1]!=0;d.starts.push_back(i?d.starts.back()+position_dof(s.poses.back())+(s.poses.back().rotation_fixed?0:3):unsigned(d.parameters.size()));s.poses.push_back(p);}
 d.n=d.starts.back()+position_dof(s.poses.back())+(s.poses.back().rotation_fixed?0:3);if(d.n>4096)throw std::runtime_error("dense camera Schur ceiling");s.points=read_array<V>(input/"points.bin");d.active=read_array<unsigned>(input/"active_points.bin");d.observations=read_array<Observation>(input/"observations.bin");d.by_point.resize(s.points.size());std::vector<char> active(s.points.size());for(auto i:d.active){if(i>=active.size()||active[i])throw std::runtime_error("active point IDs");if(!std::all_of(s.points[i].begin(),s.points[i].end(),[](double v){return std::isfinite(v);})||!(norm(s.points[i])>0))throw std::runtime_error("active point must be finite and nonzero");active[i]=1;}if(d.active.empty())throw std::runtime_error("no active points");for(unsigned i=0;i<d.observations.size();++i){auto& o=d.observations[i];if(o.camera>=s.poses.size()||o.track>=s.points.size()||o.auxiliary!=UINT64_MAX||o.depth!=0||!std::isfinite(o.size))throw std::runtime_error("observation data");if(active[o.track])d.by_point[o.track].push_back(i);}return {std::move(s),std::move(d)};
}
struct PointNormal {M v{},inverse{};V gradient{};std::vector<unsigned> ids;std::vector<V> cross;};
struct Normal {System schur;std::vector<PointNormal> points;std::vector<double> gradient;double cost{};std::size_t observations{};};
// 143A17620: preserve the determinant expansion and reciprocal multiplication.
// 142EFD790..142EFDB31 switches to a truncated SVD for ill-conditioned blocks.
M inverse3(M a){
 double A=a[4]*a[8]-a[5]*a[7],G=a[3]*a[7]-a[6]*a[4];
 double det=a[0]*A-(a[3]*a[8]-a[6]*a[5])*a[1]+a[2]*G;
 constexpr double condition_limit=1e10;
 if(det!=0&&std::isfinite(det)){double r=1/det;M b{A*r,(a[2]*a[7]-a[1]*a[8])*r,(a[1]*a[5]-a[2]*a[4])*r,(a[6]*a[5]-a[3]*a[8])*r,(a[0]*a[8]-a[2]*a[6])*r,(a[2]*a[3]-a[0]*a[5])*r,G*r,(a[1]*a[6]-a[0]*a[7])*r,(a[0]*a[4]-a[1]*a[3])*r};double na=0,nb=0;for(double v:a)na+=v*v;for(double v:b)nb+=v*v;if(na*nb<condition_limit*condition_limit)return b;}
 auto s=ms::five::square_svd<3>(a);M b{};for(unsigned k=0;k<3;++k)if(s.w[k]>0&&s.w[0]<=condition_limit*s.w[k]){double r=1/s.w[k];for(unsigned i=0;i<3;++i)for(unsigned j=0;j<3;++j)b[i*3+j]+=s.vt[k*3+i]*r*s.ut[k*3+j];}return b;
}
Normal assemble(const State& s,const Data& d,double lambda){Normal normal;auto& S=normal.schur;S.n=d.n;S.a.resize(d.n*d.n);S.pattern.resize(d.n*d.n);for(unsigned i=0;i<d.n;++i)S.pattern[i*d.n+i]=1;S.b.resize(d.n);normal.gradient.resize(d.n);normal.points.reserve(d.active.size());
 for(auto point:d.active){PointNormal p;std::map<unsigned,V> cross;for(auto oi:d.by_point[point]){auto& o=d.observations[oi];auto& pose=s.poses[o.camera];auto e=evaluate(s.calibration.data(),pose,s.points[point],o,true,d.parameters);normal.cost+=e.cost;++normal.observations;unsigned n=unsigned(e.jacobian.size())-3;std::vector<unsigned> ids(n);auto fitted_count=d.parameters.size();std::iota(ids.begin(),ids.begin()+fitted_count,0);std::iota(ids.begin()+fitted_count,ids.end(),d.starts[o.camera]);
   for(unsigned i=0;i<n;++i){auto Ji=e.jacobian[i];normal.gradient[ids[i]]+=Ji[0]*e.residual[0]+Ji[1]*e.residual[1];for(unsigned j=0;j<n;++j){auto Jj=e.jacobian[j];S.a[ids[i]*d.n+ids[j]]+=Ji[0]*Jj[0]+Ji[1]*Jj[1];}auto& w=cross[ids[i]];for(unsigned j=0;j<3;++j)w[j]+=Ji[0]*e.jacobian[n+j][0]+Ji[1]*e.jacobian[n+j][1];}
   for(unsigned i=0;i<3;++i){auto Ji=e.jacobian[n+i];p.gradient[i]+=Ji[0]*e.residual[0]+Ji[1]*e.residual[1];for(unsigned j=0;j<3;++j)p.v[i*3+j]+=Ji[0]*e.jacobian[n+j][0]+Ji[1]*e.jacobian[n+j][1];}}
  for(unsigned i=0;i<3;++i)p.v[i*3+i]*=1+lambda;p.inverse=inverse3(p.v);for(auto& [id,w]:cross){p.ids.push_back(id);p.cross.push_back(w);}normal.points.push_back(std::move(p));}
 for(auto& prior:d.priors){auto e=evaluate_prior(s.calibration.data(),prior,d.parameters);normal.cost+=e.cost;for(unsigned i=0;i<d.parameters.size();++i){normal.gradient[i]+=e.diagonal[i]*e.residual[i];S.a[i*d.n+i]+=e.diagonal[i]*e.diagonal[i];}}
 S.b=normal.gradient;for(unsigned i=0;i<d.n;++i)S.a[i*d.n+i]*=1+lambda;
 for(auto& p:normal.points){auto b=mv(p.inverse,p.gradient);for(unsigned i=0;i<p.ids.size();++i){auto w=p.cross[i];S.b[p.ids[i]]-=w[0]*b[0]+w[1]*b[1]+w[2]*b[2];auto z=mv(p.inverse,w);for(unsigned j=0;j<p.ids.size();++j){auto v=p.cross[j];S.pattern[p.ids[i]*d.n+p.ids[j]]=1;S.a[p.ids[i]*d.n+p.ids[j]]-=z[0]*v[0]+z[1]*v[1]+z[2]*v[2];}}}return normal;
}
std::vector<V> back_substitute(const Normal& n,std::span<const double> delta){std::vector<V> result;for(auto& p:n.points){auto b=p.gradient;for(unsigned i=0;i<p.ids.size();++i)for(unsigned k=0;k<3;++k)b[k]-=p.cross[i][k]*delta[p.ids[i]];result.push_back(mv(p.inverse,b));}return result;}
State trial(const State& s,const Data& d,std::span<const double> delta,const std::vector<V>& points,double alpha){State t=s;for(unsigned i=0;i<d.parameters.size();++i){unsigned bit=d.parameters[i],offset=24+8*bit+(bit>=6?8:0);set(t.calibration.data(),offset,get<double>(s.calibration.data(),offset)+alpha*delta[i]);}for(unsigned i=0;i<t.poses.size();++i){unsigned start=d.starts[i],count=position_dof(t.poses[i])+(t.poses[i].rotation_fixed?0:3);std::vector<double> v(count);for(unsigned k=0;k<count;++k)v[k]=alpha*delta[start+k];update(t.poses[i],v);}for(unsigned i=0;i<d.active.size();++i){auto id=d.active[i];auto scale=point_scale(s.points[id]);for(unsigned k=0;k<3;++k)t.points[id][k]+=points[i][k]*alpha*scale;}return t;}
double cost(const State& s,const Data& d){double sum=0;for(auto& prior:d.priors)sum+=evaluate_prior(s.calibration.data(),prior,d.parameters).cost;
 // 142EE1710 -> 142EE0F90: static partition of active points, each worker
 // accumulates observations into its local double, then OpenMP adds the totals.
 // A flat serial sum changes near-convergence line-search decisions.
#ifdef MS_NATIVE_PARALLEL_COST
#pragma omp parallel for schedule(static) reduction(+:sum)
#endif
 for(long long index=0;index<static_cast<long long>(d.active.size());++index){auto point=d.active[index];for(auto oi:d.by_point[point]){auto& o=d.observations[oi];sum+=evaluate(s.calibration.data(),s.poses[o.camera],s.points[point],o,false).cost;}}return sum;}
void output(const State& s,const Data& d,fs::path input,fs::path out){write_bytes(out/"calibration.bin",s.calibration);write_array(out/"points.bin",s.points);std::vector<double> poses;for(auto& p:s.poses){auto c=center(p);poses.insert(poses.end(),c.begin(),c.end());poses.insert(poses.end(),p.rotation.begin(),p.rotation.end());}write_array(out/"poses.bin",poses);std::ofstream json(out/"calibration.json");json<<std::setprecision(17)<<"{";const char* names[]{"f","cx","cy","k1","k2","k3","p1","p2"};for(unsigned i=0;i<8;++i){if(i)json<<",";auto bit=fitted[i];json<<'"'<<names[i]<<"\":"<<get<double>(s.calibration.data(),24+8*bit+(bit>=6?8:0));}json<<"}";
 std::ofstream xml(out/"cameras.xml");xml<<std::setprecision(17)<<"<?xml version=\"1.0\"?><document version=\"2.0.0\"><chunk><sensors ><sensor id=\"0\" type=\"frame\"><resolution width=\""<<get<std::uint64_t>(s.calibration.data(),8)<<"\" height=\""<<get<std::uint64_t>(s.calibration.data(),16)<<"\"/><calibration type=\"frame\" class=\"adjusted\"><resolution width=\""<<get<std::uint64_t>(s.calibration.data(),8)<<"\" height=\""<<get<std::uint64_t>(s.calibration.data(),16)<<"\"/>";for(unsigned i=0;i<8;++i){auto bit=fitted[i];xml<<'<'<<names[i]<<'>'<<get<double>(s.calibration.data(),24+8*bit+(bit>=6?8:0))<<"</"<<names[i]<<'>'; }xml<<"</calibration></sensor></sensors><cameras >";for(unsigned i=0;i<s.poses.size();++i){auto& p=s.poses[i];auto c=center(p);xml<<"<camera id=\""<<i<<"\" sensor_id=\"0\" label=\""<<std::setw(4)<<std::setfill('0')<<i+1<<"\"><transform>";for(unsigned j=0;j<3;++j){for(unsigned k=0;k<3;++k)xml<<p.rotation[k*3+j]<<' ';xml<<c[j]<<' ';}xml<<"0 0 0 1</transform></camera>";}xml<<"</cameras>";if(fs::exists(input/"region.xml")){auto region=read_bytes(input/"region.xml");xml.write((const char*)region.data(),region.size());}xml<<"</chunk></document>";
}
void export_sparse(const State& s,const Data& d,fs::path out){
 fs::create_directories(out);
 auto write=[&](fs::path file,std::size_t count,const char* properties,std::span<const std::byte> payload){std::ofstream f(file,std::ios::binary);f<<"ply\nformat binary_little_endian 1.0\nelement vertex "<<count<<"\n"<<properties<<"end_header\n";f.write((const char*)payload.data(),payload.size());if(!f)throw std::runtime_error("sparse export failed");};
 struct Point{float x,y,z;unsigned id;};std::vector<Point> points;for(auto id:d.active){auto p=s.points[id];points.push_back({float(p[0]),float(p[1]),float(p[2]),id});}
 write(out/"points0.ply",points.size(),"property float x\nproperty float y\nproperty float z\nproperty uint id\n",std::as_bytes(std::span(points)));
 struct Projection{float x,y,size;unsigned id;};std::vector<std::vector<Projection>> views(s.poses.size());for(auto& o:d.observations)views[o.camera].push_back({o.u,o.v,o.size,o.track});for(unsigned i=0;i<views.size();++i)write(out/("p"+std::to_string(i)+".ply"),views[i].size(),"property float x\nproperty float y\nproperty float size\nproperty int id\n",std::as_bytes(std::span(views[i])));
}
int wmain(int argc,wchar_t** argv){try{if(argc!=4)throw std::runtime_error("usage: ms_bundle_adjust prepare|normal|solve|prepare-stage|normal-stage|solve-stage INPUT NEW_OUTPUT");std::wstring mode=argv[1];fs::path input=argv[2],out=argv[3];bool stage=mode==L"prepare-stage"||mode==L"normal-stage"||mode==L"solve-stage";if(mode==L"prepare"||mode==L"prepare-stage"){prepare(input,out,stage);return 0;}if(fs::exists(out))throw std::runtime_error("output exists");auto [s,d]=load(input,stage);fs::create_directories(out);if(mode==L"normal"||mode==L"normal-stage"){auto n=assemble(s,d,0);write_array(out/"matrix.bin",n.schur.a);write_array(out/"rhs.bin",n.schur.b);auto step=solve(n.schur);write_array(out/"camera_step.bin",step);write_array(out/"point_step.bin",back_substitute(n,step));std::ofstream(out/"summary.json")<<std::setprecision(17)<<"{\"unknowns\":"<<d.n<<",\"cost\":"<<n.cost<<",\"observations\":"<<n.observations<<"}";return 0;}if(mode!=L"solve"&&mode!=L"solve-stage")throw std::runtime_error("unknown mode");double lambda=0;std::ofstream log(out/"iterations.jsonl");log<<std::setprecision(17);double initial=cost(s,d),current=initial;unsigned accepted=0;bool converged=false;
 for(unsigned iteration=0;iteration<d.iteration_limit;++iteration){try{auto n=assemble(s,d,lambda);auto delta=solve(n.schur);auto dp=back_substitute(n,delta);double direction=std::inner_product(delta.begin(),delta.end(),n.gradient.begin(),0.0);for(unsigned i=0;i<dp.size();++i)for(unsigned k=0;k<3;++k)direction+=dp[i][k]*n.points[i].gradient[k];double alpha=1,candidate_cost=current;State candidate;while(alpha>1e-10){candidate=trial(s,d,delta,dp,alpha);candidate_cost=cost(candidate,d);if(std::isfinite(candidate_cost)&&current-alpha*0.001*direction>=candidate_cost)break;alpha*=0.5;}log<<"{\"iteration\":"<<iteration<<",\"lambda\":"<<lambda<<",\"cost_before\":"<<current<<",\"cost_after\":"<<candidate_cost<<",\"alpha\":"<<alpha<<",\"direction_dot\":"<<direction<<"}\n";log.flush();std::cout<<iteration<<" cost "<<current<<" -> "<<candidate_cost<<" alpha "<<alpha<<std::endl;if(alpha<=1e-10||!(candidate_cost<current)){converged=true;break;}double a=0,b=0;for(double v:delta)a+=v*v;for(auto p:dp)for(double v:p)b+=v*v;s=std::move(candidate);current=candidate_cost;++accepted;lambda/=10;if(std::sqrt(a/d.n)*alpha<d.tolerance&&std::sqrt(b/(3*dp.size()))*alpha<d.tolerance){converged=true;break;}}catch(const std::exception& e){log<<"{\"iteration\":"<<iteration<<",\"linear_failure\":true,\"lambda\":"<<lambda<<"}\n";std::cerr<<e.what()<<std::endl;lambda=lambda==0?0.001:lambda*10;}}
 output(s,d,input,out);export_sparse(s,d,out/"sparse");std::ofstream(out/"summary.json")<<std::setprecision(17)<<"{\"initial_cost\":"<<initial<<",\"final_cost\":"<<current<<",\"accepted_iterations\":"<<accepted<<",\"calibration_priors\":"<<d.priors.size()<<",\"iteration_limit\":"<<d.iteration_limit<<",\"step_tolerance\":"<<d.tolerance<<",\"native_iteration_budget_reached\":"<<(d.captured_stage&&accepted==d.iteration_limit?"true":"false")<<",\"termination_reached\":"<<(converged?"true":"false")<<",\"native_code_called\":false,\"captured_initial_calibration_read\":"<<(d.captured_stage?"true":"false")<<",\"captured_final_calibration_read\":false,\"captured_normal_equations_read\":false,\"native_initial_poses_and_sparse_points_used\":true,\"photos_only\":false}";return (converged||(d.captured_stage&&accepted==d.iteration_limit))?0:3;}catch(const std::exception& e){std::cerr<<e.what()<<std::endl;return 2;}}
